18	 *
19	 * Mirrors GitHub Actions: combinations are generated by iterating the axes in
20	 * declaration order. An empty axis collapses the whole product to zero rows.
21	 */
22	export function cartesianProduct(axes: Axes): Combination[] {
23	  // Start with a single empty combination and fold each axis into it.
24	  let combos: Combination[] = [{}];
25	  for (const [key, values] of Object.entries(axes)) {
26	    const next: Combination[] = [];
27	    for (const combo of combos) {
28	      for (const value of values) {
29	        next.push({ ...combo, [key]: value });
30	      }
31	    }
32	    combos = next;
33	  }
34	  return combos;
35	}
