37	/** Full generator config supplied by the user (typically parsed from JSON). */
38	export interface MatrixConfig {
39	  /** The matrix axes: os, language versions, feature flags, etc. */
40	  matrix: Axes;
41	  /** Combinations to add/extend, following GitHub `include` semantics. */
42	  include?: Combination[];
43	  /** Combinations to remove if they match all listed key/value pairs. */
44	  exclude?: Combination[];
45	  /** Maximum number of concurrent jobs (GitHub `max-parallel`). */
46	  maxParallel?: number;
47	  /** Whether to cancel in-progress jobs when one fails (GitHub `fail-fast`). */
48	  failFast?: boolean;
49	  /** Hard cap on the number of generated combinations; exceeding it is an error. */
50	  maxSize?: number;
51	}
52	
53	/** Error thrown when the generated matrix exceeds the configured `maxSize`. */
54	export class MatrixSizeError extends Error {
55	  constructor(
56	    public readonly size: number,
57	    public readonly maxSize: number,
58	  ) {
59	    super(
60	      `Generated matrix has ${size} combinations, which exceeds the maximum of ${maxSize}`,
61	    );
62	    this.name = "MatrixSizeError";
63	  }
64	}
