71	/** Remove any combination that matches all key/value pairs of an exclude entry.
72	 *
73	 * An exclude entry may be partial: `{ os: "windows" }` drops every windows row.
74	 */
75	export function applyExclude(
76	  combos: Combination[],
77	  exclude: Combination[],
78	): Combination[] {
79	  if (exclude.length === 0) return combos;
80	  return combos.filter(
81	    (combo) => !exclude.some((entry) => matches(combo, entry)),
82	  );
83	}
