86	 *
87	 * For each include object: if its key/value pairs can be added to an existing
88	 * combination WITHOUT overwriting any of that combination's original axis
89	 * values, the extra fields are merged into every compatible combination.
90	 * Otherwise the include object becomes a brand-new combination of its own.
91	 *
92	 * "Original axis values" are the keys produced by the cartesian product; an
93	 * include may freely overwrite a value that a previous include added.
94	 */
95	export function applyInclude(
96	  combos: Combination[],
97	  include: Combination[],
98	  originalKeys: Set<string>,
99	): Combination[] {
100	  // `base` holds the original cartesian rows (mutated as includes extend them).
101	  // Only these rows are candidates for extension; rows created by an include
102	  // are collected in `extras` and never extended by later includes — this is
103	  // the subtle part of GitHub's algorithm.
104	  const base = combos.map((c) => ({ ...c }));
105	  const extras: Combination[] = [];
106	
107	  for (const entry of include) {
108	    let added = false;
109	    for (const combo of base) {
110	      // The include is incompatible if it tries to change an original axis
111	      // value to something different than the combination already has.
112	      const conflicts = Object.entries(entry).some(
113	        ([key, value]) =>
114	          originalKeys.has(key) && key in combo && combo[key] !== value,
115	      );
116	      if (conflicts) continue;
117	      // Compatible: merge the extra fields in (added fields may be overwritten).
118	      Object.assign(combo, entry);
119	      added = true;
120	    }
121	    if (!added) {
122	      // Could not extend any original combination -> new standalone row.
123	      extras.push({ ...entry });
124	    }
125	  }
126	  return [...base, ...extras];
127	}
