  cpSync,
  existsSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  writeFileSync,
  appendFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const PROJECT = import.meta.dir;
const WORKFLOW = join(PROJECT, ".github/workflows/environment-matrix-generator.yml");
