  for (const f of [
    "matrix-generator.ts",
    "summarize.ts",
    "matrix-generator.test.ts",
    "cli.test.ts",
    "package.json",
    ".actrc",
    ".github",
    "fixtures",
  ]) {
    const src = join(PROJECT, f);
    if (existsSync(src)) cpSync(src, join(dir, f), { recursive: true });
